insert into public.quiz_bank (title, description, group_id, quiz_type, difficulty, category, questions, scheduled_date, status, verified_at, verification_notes)
values
  ('ZEROBASEONE: From Boys Planet to In Bloom', 'How ZEROBASEONE began: the 2023 show Boys Planet, their label and name, the debut EP led by In Bloom and their first wins.', 72, 'multiple_choice', 'easy', 'group_specific', '[{"question":"On which TV channel did Boys Planet, the 2023 show that formed ZEROBASEONE, air?","options":["Mnet","JTBC","SBS","KBS2"],"correct":0,"fun_fact":"Boys Planet ran from February 2 to April 20, 2023, and 98 contestants competed for the nine spots in the debut lineup.","source":"https://en.wikipedia.org/wiki/Boys_Planet"},{"question":"Boys Planet was presented as the sequel to which earlier Mnet survival show?","options":["Girls Planet 999","Produce 101","I-LAND","Queendom"],"correct":0,"fun_fact":"The show used a space theme: its hosts were called Star Masters and the viewers who voted were called Star Creators.","source":"https://en.wikipedia.org/wiki/Boys_Planet"},{"question":"Who finished first in the final Boys Planet ranking in April 2023?","options":["Sung Han-bin","Zhang Hao","Kim Ji-woong","Seok Matthew"],"correct":1,"fun_fact":"His prize for first place was a solo song, Always, which closes the debut EP Youth in the Shade.","source":"https://en.wikipedia.org/wiki/Youth_in_the_Shade"},{"question":"ZEROBASEONE debuted in 2023 under which CJ ENM label?","options":["Cube Entertainment","Starship Entertainment","Pledis Entertainment","WakeOne"],"correct":3,"fun_fact":"WakeOne began in 2014 as MMO Entertainment, a name taken from Music Makes One, the slogan of the music channel Mnet.","source":"https://en.wikipedia.org/wiki/WakeOne"},{"question":"The name ZEROBASEONE describes the members'' journey from what to what?","options":["From one to nine","From zero to one","From the base to the summit","From dawn to dusk"],"correct":1,"fun_fact":"When the group formed in 2023, the name was explained as nine trainees starting from zero and becoming one after their debut; it is shortened to ZB1.","source":"https://en.wikipedia.org/wiki/Zerobaseone"},{"question":"Which song led ZEROBASEONE''s July 2023 debut EP, Youth in the Shade?","options":["Crush","Feel the Pop","In Bloom","Sweat"],"correct":2,"fun_fact":"Youth in the Shade went on to become the first K-pop debut album to sell more than two million copies.","source":"https://en.wikipedia.org/wiki/Youth_in_the_Shade"},{"question":"In Bloom samples the main riff of which 1984 hit?","options":["Careless Whisper","Smalltown Boy","Take On Me","Girls Just Want to Have Fun"],"correct":2,"fun_fact":"The sampled riff comes from the Norwegian band a-ha, and Billboard later put In Bloom on its list of the 25 best K-pop songs of 2023.","source":"https://en.wikipedia.org/wiki/In_Bloom_(Zerobaseone_song)"},{"question":"Eight days after debuting, ZEROBASEONE took their first trophy on which program?","options":["Inkigayo","Music Bank","M Countdown","The Show"],"correct":3,"fun_fact":"Less than a month later, on August 15, 2023, the group held its first fan concert at Gocheok Sky Dome for an audience of 18,000.","source":"https://en.wikipedia.org/wiki/Zerobaseone"},{"question":"Which single led ZEROBASEONE''s second EP, Melting Point, in November 2023?","options":["Crush","Good So Bad","Feel the Pop","Blue"],"correct":0,"fun_fact":"The EP title draws a parallel between ice melting at 0 degrees Celsius and the group''s drive to build a new world with its music.","source":"https://en.wikipedia.org/wiki/Melting_Point_(EP)"},{"question":"What was ZEROBASEONE''s sweep of rookie prizes across 2023 and 2024 called?","options":["Perfect All-Kill","Rookie Grand Slam","Triple Crown","Daesang Sweep"],"correct":1,"fun_fact":"They took ten Rookie of the Year awards at domestic ceremonies, including the Golden Disc, MAMA, Melon and Seoul Music Awards.","source":"https://en.wikipedia.org/wiki/Zerobaseone"}]'::jsonb, '2026-11-13'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Boys_Planet ; https://en.wikipedia.org/wiki/Youth_in_the_Shade ; https://en.wikipedia.org/wiki/WakeOne ; https://en.wikipedia.org/wiki/Zerobaseone ; https://en.wikipedia.org/wiki/In_Bloom_(Zerobaseone_song) ; https://en.wikipedia.org/wiki/Melting_Point_(EP) ; https://www.nme.com/news/music/zerobaseone-in-bloom-boys-planet-3465475 ; https://www.koreaherald.com/view.php?ud=20230711000665. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop Agency Founders', 'Who started SM, YG, Big Hit, Cube, Pledis, FNC and more? Ten questions on K-pop agencies, their founders and how they began.', null, 'multiple_choice', 'easy', 'knowledge', '[{"question":"Lee Soo-man''s company took the name SM Entertainment in which year?","options":["2001","1985","1995","2008"],"correct":2,"fun_fact":"SM had started out as SM Studio in 1989, and under its new name it launched the boy band H.O.T. in 1996.","source":"https://en.wikipedia.org/wiki/SM_Entertainment"},{"question":"Yang Hyun-suk, a former member of Seo Taiji and Boys, founded which agency?","options":["YG Entertainment","SM Entertainment","JYP Entertainment","DSP Media"],"correct":0,"fun_fact":"YG began as Hyun Planning and was later renamed Yang Goon Planning, after Yang Hyun-suk''s nickname Yang Goon.","source":"https://en.wikipedia.org/wiki/YG_Entertainment"},{"question":"Who founded Big Hit Entertainment, the company known today as HYBE?","options":["Han Sung-soo","Lee Jung-yeop","Bang Si-hyuk","Hong Seung-sung"],"correct":2,"fun_fact":"Big Hit was set up in 2005, signed the vocal trio 8Eight in 2007 and debuted BTS on June 13, 2013.","source":"https://en.wikipedia.org/wiki/Hybe"},{"question":"Hong Seung-sung, a former president of JYP, co-founded which agency in 2006?","options":["Cube Entertainment","Woollim Entertainment","FNC Entertainment","Starship Entertainment"],"correct":0,"fun_fact":"Cube was founded as Playcube Inc., and its first two groups debuted in 2009: 4Minute in June and Beast in October.","source":"https://en.wikipedia.org/wiki/Cube_Entertainment"},{"question":"Pledis Entertainment, founded by Han Sung-soo in 2007, is named after what?","options":["A river in Seoul","A Greek goddess","A Latin word for pleasure","The Pleiades star cluster"],"correct":3,"fun_fact":"Son Dam-bi was the first artist to debut under Pledis, and After School became its first girl group in 2009.","source":"https://en.wikipedia.org/wiki/Pledis_Entertainment"},{"question":"Singer and producer Han Seong-ho founded which agency in 2006?","options":["Pledis Entertainment","FNC Entertainment","Jellyfish Entertainment","KQ Entertainment"],"correct":1,"fun_fact":"FNC stands for fish and cake, and the label is home to the band N.Flying and the groups SF9 and P1Harmony.","source":"https://en.wikipedia.org/wiki/FNC_Entertainment"},{"question":"Lee Jung-yeop founded which agency in 2003, later the home of Infinite?","options":["Cube Entertainment","Woollim Entertainment","Jellyfish Entertainment","Starship Entertainment"],"correct":1,"fun_fact":"Infinite debuted in June 2010 as Woollim''s first boy group, and Lovelyz followed in November 2014 as its first girl group.","source":"https://en.wikipedia.org/wiki/Woollim_Entertainment"},{"question":"Which rapper was the first artist Psy signed to his agency P Nation, in January 2019?","options":["CL","Jamie","Lee Young-ji","Jessi"],"correct":3,"fun_fact":"Psy founded P Nation after leaving YG Entertainment in 2018, and in 2021 the label teamed up with JYP for the survival show Loud.","source":"https://en.wikipedia.org/wiki/P_Nation"},{"question":"YG producer Teddy Park co-founded which label?","options":["KQ Entertainment","P Nation","High Up Entertainment","The Black Label"],"correct":3,"fun_fact":"The label''s first girl group, MEOVV, debuted on September 6, 2024.","source":"https://en.wikipedia.org/wiki/The_Black_Label"},{"question":"Which production duo founded High Up Entertainment, the agency of STAYC?","options":["Duble Sidekick","LDN Noise","Black Eyed Pilseung","Sweetune"],"correct":2,"fun_fact":"High Up was set up in 2017 together with CJ E&M, and STAYC debuted on November 12, 2020 with So Bad.","source":"https://en.wikipedia.org/wiki/High_Up_Entertainment"}]'::jsonb, '2026-11-14'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/SM_Entertainment ; https://www.wikidata.org/wiki/Q483938 ; https://www.koreatimes.co.kr/entertainment/k-pop/20250203/sm-entertainment-founder-lee-soo-man-expands-beyond-k-pop ; https://en.wikipedia.org/wiki/YG_Entertainment ; https://www.wikidata.org/wiki/Q50595 ; https://en.wikipedia.org/wiki/Hybe ; https://en.wikipedia.org/wiki/BigHit_Music ; https://www.wikidata.org/wiki/Q16161254 ; https://en.wikipedia.org/wiki/Cube_Entertainment ; https://www.koreaherald.com/article/1701761 ; https://en.wikipedia.org/wiki/Pledis_Entertainment ; https://www.koreaherald.com/article/2653970 ; https://en.wikipedia.org/wiki/FNC_Entertainment ; https://www.koreatimes.co.kr/www/art/2024/10/398_130953.html ; https://en.wikipedia.org/wiki/Woollim_Entertainment ; https://www.koreatimes.co.kr/entertainment/k-pop/20230521/2nd-generation-boy-bands-return-to-shake-up-k-pop-scene ; https://en.wikipedia.org/wiki/P_Nation ; https://www.wikidata.org/wiki/Q61410007 ; https://en.wikipedia.org/wiki/The_Black_Label ; https://www.wikidata.org/wiki/Q24866458 ; https://en.wikipedia.org/wiki/High_Up_Entertainment ; https://www.koreatimes.co.kr/entertainment/k-pop/20220221/small-k-pop-labels-rising. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('LE SSERAFIM: The EASY to HOT Era', 'LE SSERAFIM in 2024 and 2025: the EPs Easy, Crazy and Hot, their Billboard firsts, remixes, awards and first world tour.', 11, 'multiple_choice', 'medium', 'era', '[{"question":"When LE SSERAFIM''s EP Easy entered the Billboard 200 at No. 8 in 2024, which group''s EP was No. 1?","options":["Stray Kids","aespa","NewJeans","TWICE"],"correct":3,"fun_fact":"TWICE topped the chart with With You-th, making them and LE SSERAFIM the first all-female K-pop acts in the Billboard 200 top 10 together.","source":"https://www.billboard.com/music/chart-beat/twice-le-sserafim-first-2-all-female-k-pop-groups-billboard-200-top-10-together-1235621542/"},{"question":"Which 2024 single gave LE SSERAFIM their first entry on the Billboard Hot 100?","options":["Smart","Crazy","Easy","Hot"],"correct":2,"fun_fact":"Easy also peaked at No. 3 on the Circle Digital Chart and won nine first place trophies on Korean music shows.","source":"https://en.wikipedia.org/wiki/Easy_(Le_Sserafim_song)"},{"question":"Smart, the second single from the EP Easy, was described as which style of song?","options":["Bossa nova ballad","Drum and bass","Country rock","Afropop-inspired amapiano"],"correct":3,"fun_fact":"Huh Yunjin is among its co-writers, and an English version arrived on March 22, 2024 along with a set of remixes.","source":"https://en.wikipedia.org/wiki/Smart_(song)"},{"question":"Which dance style shapes the choreography of LE SSERAFIM''s 2024 single Crazy?","options":["Krumping","Voguing","Tap dance","Breakdancing"],"correct":1,"fun_fact":"In the video the members dance with the House of Juicy Couture vogue team, and a remix with ballroom performer Dashaun Wesley followed.","source":"https://en.wikipedia.org/wiki/Crazy_(Le_Sserafim_song)"},{"question":"Which French DJ and producer released a remix of Crazy in September 2024?","options":["David Guetta","Martin Garrix","Calvin Harris","Kygo"],"correct":0,"fun_fact":"His remix came out on September 9, a few days after a version featuring the British singer PinkPantheress.","source":"https://en.wikipedia.org/wiki/Crazy_(Le_Sserafim_song)"},{"question":"At the 2024 MTV Video Music Awards, which prize did LE SSERAFIM win for Easy?","options":["Best K-Pop","PUSH Performance of the Year","Video of the Year","Best New Artist"],"correct":1,"fun_fact":"At the same ceremony the group performed 1-800-Hot-N-Fun and Crazy on the pre-show.","source":"https://en.wikipedia.org/wiki/2024_MTV_Video_Music_Awards"},{"question":"Which British singer joined the April 2025 remix of LE SSERAFIM''s Hot?","options":["Jade","Dua Lipa","PinkPantheress","Charli XCX"],"correct":0,"fun_fact":"Hot led the group''s fifth EP, released on March 14, 2025, and won first place on Music Bank, Inkigayo and Show! Music Core.","source":"https://en.wikipedia.org/wiki/Hot_(Le_Sserafim_song)"},{"question":"In which city did LE SSERAFIM open the Easy Crazy Hot Tour on April 19, 2025?","options":["Tokyo","Los Angeles","Incheon","Manila"],"correct":2,"fun_fact":"Their first world tour ran to 31 shows in Asia and North America and grossed 34.1 million dollars.","source":"https://en.wikipedia.org/wiki/Easy_Crazy_Hot_Tour"},{"question":"Which BTS member is featured on LE SSERAFIM''s October 2025 single Spaghetti?","options":["Jungkook","RM","Jimin","J-Hope"],"correct":3,"fun_fact":"Billboard noted it was his first team-up with a K-pop girl group, and the single album came out on October 24, 2025.","source":"https://www.billboard.com/music/music-news/le-sserafim-bts-j-hope-spaghetti-collaboration-1236092773/"},{"question":"Which Japanese duo released The Noise with LE SSERAFIM in September 2025?","options":["YOASOBI","Yuzu","Chemistry","KinKi Kids"],"correct":0,"fun_fact":"The song samples the duo''s 2019 single Yoru ni Kakeru and was made for the 20th anniversary of the fashion site Zozotown.","source":"https://en.wikipedia.org/wiki/The_Noise_(song)"}]'::jsonb, '2026-11-15'::date, 'verified', now(), 'Sources: https://www.billboard.com/music/chart-beat/twice-le-sserafim-first-2-all-female-k-pop-groups-billboard-200-top-10-together-1235621542/ ; https://www.billboard.com/music/chart-beat/le-sserafim-hot-100-debut-easy-new-ep-1235622235/ ; https://en.wikipedia.org/wiki/Easy_(Le_Sserafim_song) ; https://en.wikipedia.org/wiki/Le_Sserafim ; https://en.wikipedia.org/wiki/Smart_(song) ; https://en.wikipedia.org/wiki/Crazy_(Le_Sserafim_song) ; https://en.wikipedia.org/wiki/2024_MTV_Video_Music_Awards ; https://en.wikipedia.org/wiki/Hot_(Le_Sserafim_song) ; https://en.wikipedia.org/wiki/Easy_Crazy_Hot_Tour ; https://www.billboard.com/music/music-news/le-sserafim-bts-j-hope-spaghetti-collaboration-1236092773/ ; https://en.wikipedia.org/wiki/Spaghetti_(song) ; https://en.wikipedia.org/wiki/The_Noise_(song). Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop Songs About Magic', 'Ten K-pop songs tied to magic, spells, wishes and fairy tales, from BTS''s Magic Shop to Red Velvet''s Zimzalabim.', null, 'multiple_choice', 'easy', 'fun', '[{"question":"BTS''s 2018 song Magic Shop comes from which album?","options":["Love Yourself: Tear","Map of the Soul: 7","BE","Wings"],"correct":0,"fun_fact":"The song was inspired by Into the Magic Shop, a memoir by James R. Doty.","source":"https://en.wikipedia.org/wiki/BTS"},{"question":"TXT''s 2019 single 9 and Three Quarters (Run Away) nods to a platform from which wizard story?","options":["The Lord of the Rings","Percy Jackson","The Chronicles of Narnia","Harry Potter"],"correct":3,"fun_fact":"It led TXT''s first studio album, The Dream Chapter: Magic, and its video shows the members finding a world where they can embrace their magic.","source":"https://en.wikipedia.org/wiki/The_Dream_Chapter:_Magic"},{"question":"Which hip-swinging move from Brown Eyed Girls'' 2009 hit Abracadabra became a craze?","options":["The Tell Me Dance","The Horse Dance","The Arrogant Dance","The Penguin Dance"],"correct":2,"fun_fact":"Its title was picked as a word meaning a conjuration, and the song spent three weeks at No. 1 on the Mnet music portal.","source":"https://en.wikipedia.org/wiki/Abracadabra_(Brown_Eyed_Girls_song)"},{"question":"Which group released Zimzalabim, a 2019 song about letting a little magic back into life?","options":["Red Velvet","Apink","TWICE","GFRIEND"],"correct":0,"fun_fact":"It led The ReVe Festival: Day 1, the first part of a trilogy, and earned the group five music show trophies.","source":"https://en.wikipedia.org/wiki/Zimzalabim"},{"question":"Girls'' Generation''s 2009 hit Genie has a Korean title meaning what?","options":["Tell Me Your Wish","Make a Wish Tonight","Rub the Magic Lamp","Wish Upon a Star"],"correct":0,"fun_fact":"A critic noted the lyrics use a lamp, a genie and Aladdin as metaphors, and the video opens with Yoona sitting in a giant lamp.","source":"https://en.wikipedia.org/wiki/Genie_(Girls%27_Generation_song)"},{"question":"In IVE''s 2024 video for Accendio, the members try to protect what object?","options":["A crystal ball","A heart-shaped magic wand","A golden key","A book of spells"],"correct":1,"fun_fact":"They are told to guard it until midnight to gain special powers, then fight dark versions of themselves for it.","source":"https://www.nme.com/news/music/ive-switch-accendio-music-video-release-3756753"},{"question":"Which rock band''s 2015 single Cinderella was a modern take on the European folktale?","options":["FTISLAND","CNBLUE","DAY6","N.Flying"],"correct":1,"fun_fact":"Vocalist Jung Yong-hwa wrote and composed it, and the song went on to earn five music show wins.","source":"https://en.wikipedia.org/wiki/Cinderella_(CNBLUE_song)"},{"question":"IU''s 2013 hit The Red Shoes was inspired by a fairy tale written by whom?","options":["Charles Perrault","The Brothers Grimm","Hans Christian Andersen","Lewis Carroll"],"correct":2,"fun_fact":"It led her album Modern Times, and the plot of its music video was adapted from the 1948 British film The Red Shoes.","source":"https://en.wikipedia.org/wiki/Modern_Times_(IU_album)"},{"question":"Gugudan debuted in 2016 with Wonderland, from an EP named after which fairy tale?","options":["Snow White","Sleeping Beauty","Rapunzel","The Little Mermaid"],"correct":3,"fun_fact":"The debut EP, Act. 1 The Little Mermaid, came out on June 28, 2016, and the group followed it with Act. 2 Narcissus in 2017.","source":"https://en.wikipedia.org/wiki/Act._1_The_Little_Mermaid"},{"question":"Which girl group released As You Wish in 2019, a song many Korean listeners play first on New Year''s Day for luck?","options":["Oh My Girl","Lovelyz","WJSN","GFRIEND"],"correct":2,"fun_fact":"It topped the Melon, Bugs and Genie real-time charts on the morning of New Year''s Day six years in a row, from 2020 to 2025.","source":"https://en.wikipedia.org/wiki/As_You_Wish"}]'::jsonb, '2026-11-16'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/BTS ; https://en.wikipedia.org/wiki/Love_Yourself:_Tear ; https://en.wikipedia.org/wiki/The_Dream_Chapter:_Magic ; https://en.wikipedia.org/wiki/Abracadabra_(Brown_Eyed_Girls_song) ; https://en.wikipedia.org/wiki/Zimzalabim ; https://en.wikipedia.org/wiki/Genie_(Girls%27_Generation_song) ; https://www.nme.com/news/music/ive-switch-accendio-music-video-release-3756753 ; https://en.wikipedia.org/wiki/Ive_Switch ; https://en.wikipedia.org/wiki/Cinderella_(CNBLUE_song) ; https://en.wikipedia.org/wiki/Modern_Times_(IU_album) ; https://en.wikipedia.org/wiki/Act._1_The_Little_Mermaid ; https://en.wikipedia.org/wiki/As_You_Wish ; https://www.koreajoongangdaily.com/entertainment/wjsns-as-you-wish-tops-local-charts-on-new-years-day-for-fourth-straight-year/11803100. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('TREASURE True or False', 'True or false? Test what you know about TREASURE, from YG Treasure Box and Boy to their Japanese releases and tours.', 24, 'true_false', 'medium', 'true_false', '[{"question":"29 trainees competed on YG Treasure Box, the program that led to TREASURE.","correct":true,"fun_fact":"The final seven were introduced as TREASURE, a second unit called Magnum followed, and the two were later merged under one name.","source":"https://en.wikipedia.org/wiki/Treasure_(band)"},{"question":"The First Step series ended with TREASURE''s first EP in January 2021.","correct":false,"fun_fact":"It ended with their first studio album, The First Step: Treasure Effect, and the series sold one million copies in five months.","source":"https://en.wikipedia.org/wiki/Treasure_(band)"},{"question":"The music video for Boy became TREASURE''s first to pass 100 million views on YouTube.","correct":true,"fun_fact":"The video for the debut single passed 10 million views within 26 hours of its release in August 2020.","source":"https://en.wikipedia.org/wiki/Treasure_(band)"},{"question":"Orange, TREASURE''s first self-produced song, was composed by Jihoon.","correct":false,"fun_fact":"Asahi composed it with Future Bounce, his first credit as a composer, and it appeared on The First Step: Chapter Three in 2020.","source":"https://en.wikipedia.org/wiki/The_First_Step:_Chapter_Three"},{"question":"Beautiful, TREASURE''s first original Japanese song, was made for the anime Black Clover.","correct":true,"fun_fact":"It served as the anime''s 13th ending theme and led the Japanese version of their debut studio album.","source":"https://en.wikipedia.org/wiki/Beautiful_(Treasure_song)"},{"question":"TREASURE won their first music show trophy with Boy in 2020.","correct":false,"fun_fact":"Their first trophy came in 2022 on Show Champion with Jikjin, the lead single of their first EP, The Second Step: Chapter One.","source":"https://en.wikipedia.org/wiki/Treasure_(band)"},{"question":"TREASURE''s first concert tour of Japan, which began in November 2022, drew about 300,000 fans.","correct":true,"fun_fact":"The tour was later extended into the Hello tour across Asia, with an estimated 420,000 people in total.","source":"https://en.wikipedia.org/wiki/Treasure_(band)"},{"question":"TREASURE''s 2023 fan meeting tour of Japan ended with a show at Tokyo Dome on November 12.","correct":true,"fun_fact":"The fan meeting tour opened in Fukuoka on September 2, 2023 and visited five Japanese cities before its Tokyo Dome finale.","source":"https://koreajoongangdaily.joins.com/2023/08/04/entertainment/kpop/treasure-yg/20230804150343796.html"},{"question":"King Kong was the lead single of TREASURE''s 2023 album Reboot.","correct":false,"fun_fact":"Reboot was led by Bona Bona, with the T5 single Move as a pre-release; King Kong came out as a digital single on May 28, 2024.","source":"https://en.wikipedia.org/wiki/Treasure_(band)"},{"question":"TREASURE had nine members when they debuted in 2020.","correct":false,"fun_fact":"They debuted with twelve members. Mashiho and Bang Ye-dam left in November 2022, and TREASURE continued as ten.","source":"https://en.wikipedia.org/wiki/Treasure_(band)"}]'::jsonb, '2026-11-17'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Treasure_(band) ; https://en.wikipedia.org/wiki/The_First_Step:_Chapter_One ; https://en.wikipedia.org/wiki/The_First_Step:_Chapter_Three ; https://en.wikipedia.org/wiki/Beautiful_(Treasure_song) ; https://en.wikipedia.org/wiki/Reboot_(Treasure_album) ; https://www.koreaherald.com/article/2790367 ; https://www.koreatimes.co.kr/entertainment/k-pop/20200810/interview-ygs-treasure-begins-journey-to-find-own-color ; https://koreajoongangdaily.joins.com/2023/01/30/entertainment/kpop/Korea-Kpop-Treasure/20230130153052997.html ; https://koreajoongangdaily.joins.com/2023/08/04/entertainment/kpop/treasure-yg/20230804150343796.html. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('DAY6: From Congratulations to Fourever', 'From The Day and Congratulations to Every DAY6, Even of Day and Fourever: ten questions on DAY6''s music, members and instruments.', 38, 'multiple_choice', 'medium', 'group_specific', '[{"question":"DAY6 made their debut on September 7, 2015 with which EP?","options":["Daydream","The Day","Sunrise","Moonrise"],"correct":1,"fun_fact":"Its lead single was Congratulations, and a week after release the EP reached No. 2 on Billboard''s World Albums chart.","source":"https://en.wikipedia.org/wiki/Day6"},{"question":"Which song kicked off the Every DAY6 monthly project in January 2017?","options":["You Were Beautiful","I Wait","I Smile","How Can I Say"],"correct":1,"fun_fact":"Billboard later placed it at No. 81 on its staff list of the 100 greatest K-pop songs of the 2010s.","source":"https://en.wikipedia.org/wiki/Day6"},{"question":"Which DAY6 studio album of June 2017 collected the first half of the Every DAY6 releases?","options":["Unlock","Moonrise","Sunrise","The Book of Us: Entropy"],"correct":2,"fun_fact":"Billboard ranked it No. 14 on its staff list of the 25 greatest K-pop albums of the 2010s.","source":"https://en.wikipedia.org/wiki/Day6"},{"question":"Young K is best known as the DAY6 player of which instrument?","options":["Drums","Bass","Keyboards","Synthesizers"],"correct":1,"fun_fact":"Hosting KBS Cool FM''s Kiss the Radio won him one of the two DJ Awards at the 2023 KBS Entertainment Awards.","source":"https://en.wikipedia.org/wiki/Young_K"},{"question":"Who sits behind the drum kit in DAY6?","options":["Wonpil","Sungjin","Dowoon","Young K"],"correct":2,"fun_fact":"He trained for only about three months at JYP Entertainment before his debut, one of the fastest debuts at the company.","source":"https://en.wikipedia.org/wiki/Dowoon"},{"question":"Which DAY6 member handles the keyboards and synthesizers?","options":["Sungjin","Dowoon","Young K","Wonpil"],"correct":3,"fun_fact":"His first solo album, Pilmography, debuted at No. 1 on the Gaon Album Chart in February 2022.","source":"https://en.wikipedia.org/wiki/Wonpil"},{"question":"Which DAY6 member is the band''s leader and plays guitar?","options":["Sungjin","Dowoon","Young K","Wonpil"],"correct":0,"fun_fact":"He released his first solo album, titled 30, on November 5, 2024, and held his first solo concert days later.","source":"https://en.wikipedia.org/wiki/Sungjin"},{"question":"Which song led The Book of Us: Gluon, the August 2020 debut EP of the unit Even of Day?","options":["Where the Sea Sleeps","Zombie","Right Through Me","You Make Me"],"correct":0,"fun_fact":"JYP founder Park Jin-young named the unit: even is an old word for night, so the name promises a bright day after a dark night.","source":"https://en.wikipedia.org/wiki/Day6_(Even_of_Day)"},{"question":"Which song was the lead single of Fourever, the EP DAY6 released on March 18, 2024?","options":["Happy","Melt Down","Welcome to the Show","Maybe Tomorrow"],"correct":2,"fun_fact":"Happy, a track from the same EP that was never a single, reached No. 1 on the Circle Digital Chart in September 2024.","source":"https://en.wikipedia.org/wiki/Fourever"},{"question":"Which DAY6 lead single from 2019 ranked No. 10 on the Circle Digital Chart for the first half of 2024?","options":["Zombie","Shoot Me","I Like You","Time of Our Life"],"correct":3,"fun_fact":"The revival rolled on into Band Aid in September 2024, an EP whose title pairs band with aid, a promise to offer help.","source":"https://en.wikipedia.org/wiki/Band_Aid_(EP)"}]'::jsonb, '2026-11-18'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Day6 ; https://en.wikipedia.org/wiki/Young_K ; https://en.wikipedia.org/wiki/Dowoon ; https://en.wikipedia.org/wiki/Wonpil ; https://en.wikipedia.org/wiki/Sungjin ; https://en.wikipedia.org/wiki/Day6_(Even_of_Day) ; https://en.wikipedia.org/wiki/Fourever ; https://en.wikipedia.org/wiki/Band_Aid_(EP) ; https://en.wikipedia.org/wiki/The_Day_(EP) ; https://en.wikipedia.org/wiki/Congratulations_(Day6_song) ; https://www.wikidata.org/wiki/Q20898046 ; https://day6.jype.com/profile ; https://en.wikipedia.org/wiki/2023_KBS_Entertainment_Awards. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('TXT: From Sugar Rush Ride to Deja Vu', 'TXT in 2023 and 2024: The Name Chapter: Temptation and Freefall, minisode 3: Tomorrow with Deja Vu, and the tours and stages of that run.', 16, 'multiple_choice', 'medium', 'era', '[{"question":"Which TXT song won Push Performance of the Year at the 2023 MTV Video Music Awards?","options":["Chasing That Feeling","Sugar Rush Ride","Do It Like That","Back for More"],"correct":1,"fun_fact":"The song also reached No. 1 on Billboard''s US World Digital Song Sales chart in 2023.","source":"https://en.wikipedia.org/wiki/Sugar_Rush_Ride"},{"question":"The January 2023 EP The Name Chapter: Temptation draws its story from which classic tale?","options":["Peter Pan","Alice in Wonderland","Pinocchio","The Little Prince"],"correct":0,"fun_fact":"American rapper Coi Leray guests on its third track, Happy Fools, and the closing ballad is called Farewell, Neverland.","source":"https://en.wikipedia.org/wiki/The_Name_Chapter:_Temptation"},{"question":"Which world tour did TXT launch in Seoul in March 2023 in support of Temptation?","options":["Act: Lovesick","Act: Promise","Act: Tomorrow","Act: Sweet Mirage"],"correct":3,"fun_fact":"The tour opened on March 25, 2023 and closed on December 3, 2023, both times in Seoul.","source":"https://en.wikipedia.org/wiki/List_of_Tomorrow_X_Together_live_performances"},{"question":"In August 2023, TXT became the first Korean group to headline which Chicago festival?","options":["Lollapalooza","Pitchfork Music Festival","Riot Fest","Chicago Blues Festival"],"correct":0,"fun_fact":"It was their second straight Lollapalooza: on July 30, 2022 they had played a set on the smaller Solana x Perry''s stage.","source":"https://www.nme.com/reviews/tomorrow-x-together-lollapalooza-2023-live-review-3478932"},{"question":"Which American band joined TXT on the July 2023 single Do It Like That?","options":["Maroon 5","OneRepublic","Jonas Brothers","Imagine Dragons"],"correct":2,"fun_fact":"Ryan Tedder produced the track after meeting TXT while they were touring the United States.","source":"https://en.wikipedia.org/wiki/Do_It_Like_That_(Tomorrow_X_Together_and_Jonas_Brothers_song)"},{"question":"Which Brazilian singer recorded the September 2023 version of Back for More with TXT?","options":["Pabllo Vittar","Ludmilla","Anitta","Luísa Sonza"],"correct":2,"fun_fact":"Mixing K-pop with Brazilian funk, it debuted at No. 41 on the Billboard Brasil Hot 100.","source":"https://en.wikipedia.org/wiki/Back_for_More_(Tomorrow_X_Together_and_Anitta_song)"},{"question":"Besides Do It Like That and Back for More, which song was a single from The Name Chapter: Freefall?","options":["Chasing That Feeling","Deja Vu","Sugar Rush Ride","Growing Pain"],"correct":0,"fun_fact":"Released on October 13, 2023, the album moved more than 2.4 million copies in South Korea in week one and opened at No. 1 on the Circle and Oricon album charts.","source":"https://en.wikipedia.org/wiki/The_Name_Chapter:_Freefall"},{"question":"In 2024, TXT recorded LeveL as the opening theme of which anime series?","options":["Jujutsu Kaisen","Chainsaw Man","Tower of God","Solo Leveling"],"correct":3,"fun_fact":"They made the song together with Japanese composer Hiroyuki Sawano.","source":"https://en.wikipedia.org/wiki/Tomorrow_X_Together"},{"question":"Which song was the lead single of minisode 3: Tomorrow, released on April 1, 2024?","options":["Miracle","Quarter Life","Deja Vu","I''ll See You There Tomorrow"],"correct":2,"fun_fact":"The EP''s second track is a seven-second piece whose title is written in Morse code that reads tomorrow.","source":"https://en.wikipedia.org/wiki/Minisode_3:_Tomorrow"},{"question":"Act: Promise, TXT''s 2024 tour for minisode 3, opened on May 3 at which Seoul venue?","options":["Gocheok Sky Dome","KSPO Dome","Jamsil Indoor Stadium","Inspire Arena"],"correct":1,"fun_fact":"The Japan leg of the tour began on July 10, 2024 at the Tokyo Dome.","source":"https://en.wikipedia.org/wiki/List_of_Tomorrow_X_Together_live_performances"}]'::jsonb, '2026-11-19'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Sugar_Rush_Ride ; https://en.wikipedia.org/wiki/The_Name_Chapter:_Temptation ; https://en.wikipedia.org/wiki/List_of_Tomorrow_X_Together_live_performances ; https://www.nme.com/reviews/tomorrow-x-together-lollapalooza-2023-live-review-3478932 ; https://en.wikipedia.org/wiki/Do_It_Like_That_(Tomorrow_X_Together_and_Jonas_Brothers_song) ; https://en.wikipedia.org/wiki/Back_for_More_(Tomorrow_X_Together_and_Anitta_song) ; https://en.wikipedia.org/wiki/The_Name_Chapter:_Freefall ; https://en.wikipedia.org/wiki/Tomorrow_X_Together ; https://en.wikipedia.org/wiki/Minisode_3:_Tomorrow ; https://en.wikipedia.org/wiki/2023_MTV_Video_Music_Awards ; https://www.koreaherald.com/article/3085666. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop Songs of 2025', 'Ten acts, ten songs from 2025: match Jump, Dirty Work, Earthquake, Good Goodbye and more to the K-pop act that released them.', null, 'multiple_choice', 'medium', 'knowledge', '[{"question":"Which group released Jump in July 2025 as the lead single of its EP Deadline?","options":["BABYMONSTER","aespa","ITZY","BLACKPINK"],"correct":3,"fun_fact":"It became the group''s third No. 1 on the Billboard Global 200, and Dave Meyers directed its music video.","source":"https://en.wikipedia.org/wiki/Jump_(Blackpink_song)"},{"question":"Dirty Work, out in June 2025 as the title track of a first single album, is by which group?","options":["ITZY","Kep1er","i-dle","aespa"],"correct":3,"fun_fact":"Apple co-produced its performance video, shot from start to finish on an iPhone 16 Pro, and the song went on to win four music show trophies.","source":"https://en.wikipedia.org/wiki/Dirty_Work_(Aespa_song)"},{"question":"Who released Earthquake on February 14, 2025 as the lead single of her debut EP, Amortage?","options":["Jisoo","Rosé","Taeyeon","Chungha"],"correct":0,"fun_fact":"It became her first No. 1 on Billboard''s World Digital Song Sales chart and her first single under her own label, Blissoo.","source":"https://en.wikipedia.org/wiki/Earthquake_(Jisoo_song)"},{"question":"Whose May 2025 EP Echo was led by the single Don''t Say You Love Me?","options":["Baekhyun","Taemin","Kai","Jin"],"correct":3,"fun_fact":"Its music video was shot in Singapore with actress Shin Se-kyung, the first time Jin worked with an actor.","source":"https://en.wikipedia.org/wiki/Don''t_Say_You_Love_Me_(Jin_song)"},{"question":"Which BTS member released Mona Lisa in March 2025 after previewing it at Brooklyn''s Barclays Center?","options":["RM","J-Hope","Suga","Jungkook"],"correct":1,"fun_fact":"Blake Slatkin, Cashmere Cat and Misogi share the production credit, and J-Hope told his Brooklyn crowd the song was his way of showing love to ARMY.","source":"https://en.wikipedia.org/wiki/Mona_Lisa_(J-Hope_song)"},{"question":"Good Thing, the May 2025 lead single of the EP We Are, comes from which group?","options":["TWICE","aespa","i-dle","STAYC"],"correct":2,"fun_fact":"Soyeon wrote it and co-composed it with Pop Time, Daily and Likey, drawing on early 2000s autotune styles.","source":"https://en.wikipedia.org/wiki/Good_Thing_(I-dle_song)"},{"question":"Which group released the EP Girls Will Be Girls, led by its title song, in June 2025?","options":["ITZY","STAYC","Kep1er","fromis_9"],"correct":0,"fun_fact":"It was the group''s tenth EP, a five-track release put out by JYP Entertainment and Republic Records.","source":"https://en.wikipedia.org/wiki/Girls_Will_Be_Girls_(EP)"},{"question":"Fly Up was the lead single of Odyssey, the first studio album of which boy group, in May 2025?","options":["NCT Wish","TWS","RIIZE","The Boyz"],"correct":2,"fun_fact":"The song draws on 1950s rock and roll and won four first-place trophies on Korean music shows.","source":"https://en.wikipedia.org/wiki/Fly_Up"},{"question":"Who released Good Goodbye in October 2025, a song that took off after her Blue Dragon Film Awards stage?","options":["Taeyeon","BIBI","Hwasa","Lee Hi"],"correct":2,"fun_fact":"By January 2026 it had the second-most perfect all-kills of any song and the most by a soloist.","source":"https://en.wikipedia.org/wiki/Good_Goodbye_(Hwasa_song)"},{"question":"This Is For, the July 2025 lead single of a fourth Korean studio album, is by which group?","options":["ITZY","TWICE","BLACKPINK","STAYC"],"correct":1,"fun_fact":"Jihyo said the members pushed hard for this song to be the lead single, and in the end it was the one chosen.","source":"https://en.wikipedia.org/wiki/This_Is_For_(song)"}]'::jsonb, '2026-11-20'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Jump_(Blackpink_song) ; https://en.wikipedia.org/wiki/Dirty_Work_(Aespa_song) ; https://en.wikipedia.org/wiki/Earthquake_(Jisoo_song) ; https://en.wikipedia.org/wiki/Don''t_Say_You_Love_Me_(Jin_song) ; https://en.wikipedia.org/wiki/Mona_Lisa_(J-Hope_song) ; https://en.wikipedia.org/wiki/Good_Thing_(I-dle_song) ; https://en.wikipedia.org/wiki/Girls_Will_Be_Girls_(EP) ; https://en.wikipedia.org/wiki/Fly_Up ; https://en.wikipedia.org/wiki/Good_Goodbye_(Hwasa_song) ; https://en.wikipedia.org/wiki/This_Is_For_(song). Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('KPop Demon Hunters Quiz', 'An easy quiz on the 2025 Netflix film KPop Demon Hunters: its directors, HUNTR/X and the Saja Boys, the voice cast and Golden''s records.', null, 'multiple_choice', 'easy', 'fun', '[{"question":"Which studio produced KPop Demon Hunters for Netflix?","options":["Sony Pictures Animation","DreamWorks Animation","Pixar","Illumination"],"correct":0,"fun_fact":"The animation itself was done by Sony Pictures Imageworks at its Vancouver and Montreal studios.","source":"https://en.wikipedia.org/wiki/KPop_Demon_Hunters"},{"question":"Maggie Kang co-directed KPop Demon Hunters with which filmmaker?","options":["Peter Ramsey","Phil Lord","Chris Williams","Chris Appelhans"],"correct":3,"fun_fact":"Kang first pitched the idea in 2018, and Appelhans joined after hearing it despite planning a long break after Wish Dragon.","source":"https://en.wikipedia.org/wiki/KPop_Demon_Hunters"},{"question":"Who gives Rumi her speaking voice in KPop Demon Hunters?","options":["May Hong","Arden Cho","Ji-young Yoo","Liza Koshy"],"correct":1,"fun_fact":"She first auditioned for the role of Celine and then tried out for Rumi at the urging of director Maggie Kang.","source":"https://en.wikipedia.org/wiki/KPop_Demon_Hunters"},{"question":"Who provides Rumi''s singing voice in the film?","options":["EJAE","Rei Ami","Lea Salonga","Audrey Nuna"],"correct":0,"fun_fact":"She joined the production as a songwriter, and she says the directors offered her the role after hearing her voice on the demos.","source":"https://en.wikipedia.org/wiki/KPop_Demon_Hunters"},{"question":"Rei Ami is the singing voice of which character in KPop Demon Hunters?","options":["Mira","Rumi","Zoey","Celine"],"correct":2,"fun_fact":"Audrey Nuna sings for Mira, while Zoey''s speaking voice comes from Ji-young Yoo.","source":"https://en.wikipedia.org/wiki/Huntrix"},{"question":"Which of these songs from the film is performed by the Saja Boys?","options":["Your Idol","Golden","How It''s Done","Takedown"],"correct":0,"fun_fact":"In the story, the demon boy band sings it at Namsan Tower to summon their master, Gwi-Ma.","source":"https://en.wikipedia.org/wiki/Your_Idol"},{"question":"Members of which real girl group recorded the end credits version of Takedown?","options":["ITZY","BLACKPINK","TWICE","aespa"],"correct":2,"fun_fact":"Jeongyeon, Jihyo and Chaeyoung sang it, and their version came out on June 20, 2025 as the soundtrack''s lead single.","source":"https://en.wikipedia.org/wiki/Takedown_(song)"},{"question":"When Golden topped the Billboard Hot 100 in August 2025, which first did it claim?","options":["First K-pop song ever to top the chart","First K-pop No. 1 led by female vocalists","First No. 1 by a fictional act","First No. 1 from an animated film"],"correct":1,"fun_fact":"HUNTR/X also became the first all-women trio or bigger to top the chart since Destiny''s Child with Bootylicious in 2001.","source":"https://www.billboard.com/lists/huntrx-golden-kpop-demon-hunters-number-1-hot-100/"},{"question":"In August 2025, Golden became the second K-pop No. 1 on the UK singles chart. Which song was the first?","options":["How You Like That","Dynamite","APT.","Gangnam Style"],"correct":3,"fun_fact":"That same week, the Saja Boys songs Your Idol and Soda Pop climbed to No. 10 and No. 11.","source":"https://www.officialcharts.com/chart-news/kpop-demon-hunters-huntrx-golden-number-1-single/"},{"question":"In September 2025, KPop Demon Hunters passed which show to become Netflix''s most-watched title?","options":["Wednesday season 1","Stranger Things 4","Squid Game season 1","Bridgerton season 1"],"correct":2,"fun_fact":"Eight days earlier, on August 26, it had overtaken Red Notice to become Netflix''s most-watched film.","source":"https://en.wikipedia.org/wiki/KPop_Demon_Hunters"}]'::jsonb, '2026-11-21'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/KPop_Demon_Hunters ; https://en.wikipedia.org/wiki/Huntrix ; https://en.wikipedia.org/wiki/Your_Idol ; https://en.wikipedia.org/wiki/Takedown_(song) ; https://www.billboard.com/lists/huntrx-golden-kpop-demon-hunters-number-1-hot-100/ ; https://www.officialcharts.com/chart-news/kpop-demon-hunters-huntrx-golden-number-1-single/ ; https://en.wikipedia.org/wiki/Golden_(Huntrix_song) ; https://en.wikipedia.org/wiki/Arden_Cho ; https://en.wikipedia.org/wiki/Ejae ; https://en.wikipedia.org/wiki/Rei_Ami ; https://www.billboard.com/charts/hot-100/2025-08-16/. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('BOYNEXTDOOR: From WHO! to No Genre', 'An easy quiz on BOYNEXTDOOR: KOZ Entertainment, the WHO! debut, the First Love trilogy, 19.99, No Genre and their first wins.', 70, 'multiple_choice', 'easy', 'group_specific', '[{"question":"Which HYBE label formed BOYNEXTDOOR in 2023?","options":["KOZ Entertainment","Pledis Entertainment","Belift Lab","Source Music"],"correct":0,"fun_fact":"Rapper and producer Zico of Block B founded the label, which HYBE acquired in 2020.","source":"https://en.wikipedia.org/wiki/BoyNextDoor"},{"question":"With which single album did BOYNEXTDOOR debut on May 30, 2023?","options":["WHY..","WHO!","HOW?","19.99"],"correct":1,"fun_fact":"All three of its tracks, But I Like You, One and Only and Serenade, were released as singles.","source":"https://en.wikipedia.org/wiki/Who!_(single_album)"},{"question":"Which WHO! song, produced by Zico, has the members open a real door on stage?","options":["But I Like You","Serenade","One and Only","But Sometimes"],"correct":2,"fun_fact":"The six members helped create its choreography, and the door gag literally acts out the group''s name.","source":"https://www.koreaherald.com/article/3136905"},{"question":"Which song led WHY.., BOYNEXTDOOR''s first EP, in 2023?","options":["But Sometimes","Nice Guy","Dangerous","But I Like You"],"correct":0,"fun_fact":"The EP entered the Billboard 200 at No. 162, the group''s first appearance on that chart.","source":"https://en.wikipedia.org/wiki/BoyNextDoor"},{"question":"Which song led HOW?, the April 2024 EP that closed BOYNEXTDOOR''s First Love trilogy?","options":["Amnesia","Our","Nice Guy","Earth, Wind & Fire"],"correct":3,"fun_fact":"HOW? debuted at No. 1 on the Circle Album Chart, the group''s first chart-topping album.","source":"https://en.wikipedia.org/wiki/How%3F_(EP)"},{"question":"On which music show did BOYNEXTDOOR earn their first win, on April 23, 2024?","options":["The Show","Music Bank","Inkigayo","Show! Music Core"],"correct":0,"fun_fact":"That June they held their first fan meeting, OneDoorful Day, at the Olympic Hall in Seoul.","source":"https://en.wikipedia.org/wiki/BoyNextDoor"},{"question":"What does the title of BOYNEXTDOOR''s September 2024 EP 19.99 point to?","options":["The price of the album in dollars","The moment just before turning 20","The year 1999","The days they spent as trainees"],"correct":1,"fun_fact":"Its main single was Nice Guy, and the EP passed one million copies in cumulative sales in October 2024.","source":"https://en.wikipedia.org/wiki/19.99_(EP)"},{"question":"Which song was the main single of No Genre, BOYNEXTDOOR''s May 2025 EP?","options":["Hollywood Action","I Feel Good","Nice Guy","Step by Step"],"correct":1,"fun_fact":"No Genre sold 1,166,419 copies in its first five days, the group''s best opening week at the time.","source":"https://en.wikipedia.org/wiki/No_Genre_(EP)"},{"question":"Which special award did BOYNEXTDOOR win at the 2023 Melon Music Awards?","options":["Rookie of the Year","Artist of the Year","Song of the Year","Global Rising Artist"],"correct":3,"fun_fact":"That November they also released Fadeaway as the theme song of the Naver webtoon Garbage Time.","source":"https://en.wikipedia.org/wiki/BoyNextDoor"},{"question":"Which of these idols is a member of BOYNEXTDOOR?","options":["Taeyong","Taehyun","Taesan","Taemin"],"correct":2,"fun_fact":"Taesan, Jaehyun and Woonhak take an active part in producing the group''s music.","source":"https://en.wikipedia.org/wiki/BoyNextDoor"}]'::jsonb, '2026-11-22'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/BoyNextDoor ; https://en.wikipedia.org/wiki/Who!_(single_album) ; https://www.koreaherald.com/article/3136905 ; https://en.wikipedia.org/wiki/How%3F_(EP) ; https://en.wikipedia.org/wiki/19.99_(EP) ; https://en.wikipedia.org/wiki/No_Genre_(EP) ; https://www.wikidata.org/wiki/Q118178306 ; https://kozofficial.com/artist/profile/BOYNEXTDOOR ; https://www.nme.com/news/music/2023-melon-music-awards-nominations-winners-3552668 ; https://www.koreatimes.co.kr/entertainment/k-pop/20230905/boynextdoor-explores-complexities-of-young-love-in-new-album-why ; https://www.nme.com/news/music/boynextdoor-first-comeback-why-mini-album-release-date-3479688. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop Award Shows True or False', 'Ten true or false statements about the K-pop award shows themselves: who runs MAMA, Melon, Golden Disc and Seoul Music Awards, and where.', null, 'true_false', 'medium', 'true_false', '[{"question":"The awards show now known as the MAMA Awards was first held in 1999.","correct":true,"fun_fact":"The show took the Mnet Asian Music Awards name in 2009 as it set its sights beyond Korea, then shortened its brand to the MAMA Awards in 2022.","source":"https://en.wikipedia.org/wiki/MAMA_Awards"},{"question":"The first MAMA ceremony held outside South Korea took place in Singapore in 2010.","correct":false,"fun_fact":"The 2010 edition went to Macau, at the Cotai Arena of The Venetian Macao. Singapore hosted in 2011, then Hong Kong from 2012 to 2017.","source":"https://en.wikipedia.org/wiki/MAMA_Awards"},{"question":"The Melon Music Awards are presented by CJ ENM, the company behind the Mnet channel.","correct":false,"fun_fact":"They are held by Kakao Entertainment through its streaming service Melon, whose digital data counts alongside online votes and judges.","source":"https://en.wikipedia.org/wiki/Melon_Music_Awards"},{"question":"The Golden Disc Awards were first held in 1986, under the name Korea Visual and Records Grand Prize Award.","correct":true,"fun_fact":"The ceremony took the name Golden Disk Awards in 2001, and the spelling changed to Golden Disc in 2015.","source":"https://en.wikipedia.org/wiki/Golden_Disc_Awards"},{"question":"The Seoul Music Awards are presented by the sports daily Ilgan Sports.","correct":false,"fun_fact":"The Seoul Music Awards, or Seoul Gayo Daesang in Korean, are presented by the newspaper Sports Seoul and have aired on KBS N since 2013.","source":"https://en.wikipedia.org/wiki/Seoul_Music_Awards"},{"question":"The Circle Chart Music Awards used the name Gaon Chart Music Awards until the chart was rebranded in 2022.","correct":true,"fun_fact":"The awards are presented by the Korea Music Content Association, and the first ceremony took place in Seoul on February 22, 2012.","source":"https://en.wikipedia.org/wiki/Circle_Chart_Music_Awards"},{"question":"The 40th Golden Disc Awards were held at the Taipei Dome in January 2026.","correct":true,"fun_fact":"Hosted by Sung Si-kyung and Moon Ga-young on January 10, 2026, the ceremony honored Korean music released from early November 2024 to early November 2025.","source":"https://en.wikipedia.org/wiki/40th_Golden_Disc_Awards"},{"question":"The 2023 MAMA Awards took place at the Kyocera Dome in Osaka.","correct":false,"fun_fact":"The 2023 show ran over two nights at the Tokyo Dome. The Kyocera Dome in Osaka hosted in 2022 and 2024 and was chosen again for the November 2026 edition.","source":"https://en.wikipedia.org/wiki/MAMA_Awards"},{"question":"The Seoul Music Awards were held outside South Korea for the first time in January 2024, in Bangkok.","correct":true,"fun_fact":"The 33rd ceremony took place at Rajamangala Stadium. The next two editions moved to June, at Inspire Arena in Incheon.","source":"https://www.koreajoongangdaily.com/entertainment/nct-dream-wins-top-honor-at-seoul-music-awards-for-2nd-year/10376567"},{"question":"The 2023 and 2024 Melon Music Awards were both held at the Gocheok Sky Dome in Seoul.","correct":false,"fun_fact":"Both ceremonies took place at Inspire Arena in Incheon. The show returned to the Gocheok Sky Dome for its December 2025 edition.","source":"https://en.wikipedia.org/wiki/Melon_Music_Awards"}]'::jsonb, '2026-11-23'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/MAMA_Awards ; https://en.wikipedia.org/wiki/Melon_Music_Awards ; https://en.wikipedia.org/wiki/Golden_Disc_Awards ; https://en.wikipedia.org/wiki/Seoul_Music_Awards ; https://en.wikipedia.org/wiki/Circle_Chart_Music_Awards ; https://en.wikipedia.org/wiki/40th_Golden_Disc_Awards ; https://www.billboard.com/music/awards/mama-awards-2022-date-location-rebrand-1235129969/ ; https://en.wikipedia.org/wiki/2026_MAMA_Awards ; https://www.koreajoongangdaily.com/entertainment/nct-dream-wins-top-honor-at-seoul-music-awards-for-2nd-year/10376567. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('IVE: The SWITCH to EMPATHY Era', 'IVE in 2024 and 2025: Heya and Will, Rebel Heart and Attitude, Supernova Love, XOXZ, the world tour and Lollapalooza.', 10, 'multiple_choice', 'medium', 'era', '[{"question":"What does the Korean title of IVE''s April 2024 single Heya mean?","options":["Moon","Star","Sky","Sun"],"correct":3,"fun_fact":"Described as a hip hop song in F minor, Heya draws its lyrics from a folk tale and climbed to No. 2 on the Circle Digital Chart.","source":"https://en.wikipedia.org/wiki/Heya_(Ive_song)"},{"question":"Will, a Japanese song IVE released on April 12, 2024, was the new opening theme of which anime series?","options":["Pokémon Horizons","Detective Conan","One Piece","Doraemon"],"correct":0,"fun_fact":"The opening video came out on Pokémon''s official YouTube channel, and IVE''s second Japanese EP, Alive, followed on August 28, 2024.","source":"https://en.wikipedia.org/wiki/Ive_(group)"},{"question":"Which IVE member wrote the lyrics of Blue Heart, a track on the 2024 EP Ive Switch?","options":["An Yu-jin","Gaeul","Jang Won-young","Liz"],"correct":2,"fun_fact":"Blue Heart is the third of the six tracks on Ive Switch, an EP that peaked at No. 2 on the Circle Album Chart.","source":"https://en.wikipedia.org/wiki/Ive_Switch"},{"question":"IVE''s first world tour, Show What I Have, ended in September 2024 with two shows at which venue?","options":["KSPO Dome","Tokyo Dome","Kyocera Dome Osaka","Gocheok Sky Dome"],"correct":1,"fun_fact":"The tour opened in Seoul on October 7, 2023 and grew to 37 concerts across Asia, North America, Europe, Latin America and Oceania.","source":"https://en.wikipedia.org/wiki/Show_What_I_Have_World_Tour"},{"question":"Supernova Love, IVE''s November 2024 single with David Guetta, samples a piece by which Japanese composer?","options":["Ryuichi Sakamoto","Joe Hisaishi","Yoko Kanno","Koji Kondo"],"correct":0,"fun_fact":"The sampled piece is Merry Christmas, Mr. Lawrence. IVE first teased the song during encores of their world tour shows in Japan.","source":"https://en.wikipedia.org/wiki/Supernova_Love"},{"question":"Which Ive Empathy single came out first, on January 13, 2025, and went on to top the Circle Digital Chart?","options":["Attitude","Flu","TKO","Rebel Heart"],"correct":3,"fun_fact":"It became IVE''s fifth song to achieve a perfect all-kill on Korean charts and collected eleven first places on music shows.","source":"https://en.wikipedia.org/wiki/Rebel_Heart_(Ive_song)"},{"question":"Attitude, the second single from Ive Empathy, interpolates which Suzanne Vega song?","options":["Luka","Tom''s Diner","Left of Center","Marlene on the Wall"],"correct":1,"fun_fact":"Released with the EP on February 3, 2025, Attitude peaked at No. 7 on the Circle Digital Chart and won on M Countdown, Inkigayo and Show! Music Core.","source":"https://en.wikipedia.org/wiki/Attitude_(Ive_song)"},{"question":"At which 2025 ceremony did IVE''s Rebel Heart win the Song of the Year daesang?","options":["MAMA Awards","Golden Disc Awards","Melon Music Awards","Asia Artist Awards"],"correct":3,"fun_fact":"The 10th Asia Artist Awards took place on December 6, 2025 at the National Stadium in Kaohsiung, Taiwan.","source":"https://en.wikipedia.org/wiki/10th_Asia_Artist_Awards"},{"question":"After a first Lollapalooza in Chicago in 2024, IVE played which two editions of the festival in July 2025?","options":["Berlin and Santiago","Paris and Stockholm","Berlin and Paris","Mumbai and Paris"],"correct":2,"fun_fact":"On July 12, 2025, IVE became the first K-pop girl group to perform at Lollapalooza Berlin, then played the Paris edition on July 20.","source":"https://en.wikipedia.org/wiki/Ive_(group)"},{"question":"What was the lead single of Ive Secret, the EP IVE released on August 25, 2025?","options":["Gotcha (Baddest Eros)","Wild Bird","XOXZ","Midnight Kiss"],"correct":2,"fun_fact":"Ive Secret topped the Circle Album Chart, making it the group''s seventh No. 1 album and sixth million-seller.","source":"https://en.wikipedia.org/wiki/Ive_(group)"}]'::jsonb, '2026-11-24'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Heya_(Ive_song) ; https://en.wikipedia.org/wiki/Ive_Switch ; https://en.wikipedia.org/wiki/Show_What_I_Have_World_Tour ; https://en.wikipedia.org/wiki/Supernova_Love ; https://en.wikipedia.org/wiki/Rebel_Heart_(Ive_song) ; https://en.wikipedia.org/wiki/Attitude_(Ive_song) ; https://en.wikipedia.org/wiki/10th_Asia_Artist_Awards ; https://en.wikipedia.org/wiki/Ive_(group) ; https://en.wikipedia.org/wiki/Ive_Empathy ; https://en.wikipedia.org/wiki/Ive_Secret ; https://en.wikipedia.org/wiki/2025_MAMA_Awards ; https://en.wikipedia.org/wiki/2025_Melon_Music_Awards ; https://en.wikipedia.org/wiki/40th_Golden_Disc_Awards ; https://en.wikipedia.org/wiki/Alive_(Ive_EP). Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop Groups and Their First Wins', 'Which song gave TVXQ, Apink, EXO, TWICE, ITZY or TWS their first music show win, and on which show? Ten hard questions.', null, 'multiple_choice', 'hard', 'knowledge', '[{"question":"TVXQ won their first music show award on Inkigayo in March 2004. Which song won it?","options":["The Way U Are","Rising Sun","Hug","Mirotic"],"correct":2,"fun_fact":"The win came on March 28, 2004, and Hug went on to stay on the MIAK monthly chart for ten consecutive months.","source":"https://en.wikipedia.org/wiki/TVXQ"},{"question":"Beast, the group now called Highlight, got their first music show win with Shock in March 2010. On which show?","options":["Show Champion","Music Bank","Inkigayo","M Countdown"],"correct":3,"fun_fact":"Shock led their second EP, Shock of the New Era. Later in 2010, the single Breath took first place on KBS''s Music Bank.","source":"https://en.wikipedia.org/wiki/Highlight_(band)"},{"question":"Which song gave Apink their first music show award, on M Countdown in January 2012?","options":["Mollayo","Hush","My My","LUV"],"correct":2,"fun_fact":"My My came from their second EP, Snow Pink. A month later, Apink won Rookie of the Year at the first Gaon Chart Awards.","source":"https://en.wikipedia.org/wiki/Apink"},{"question":"Which single earned EXO their first music show win, on Music Bank in June 2013?","options":["Growl","Wolf","History","MAMA"],"correct":1,"fun_fact":"EXO later won 18 music shows with Call Me Baby (2015), a record for a single song that they held for four years.","source":"https://en.wikipedia.org/wiki/Exo"},{"question":"On February 2, 2016, GFriend won their first music show award on The Show. Which song won it?","options":["Me Gustas Tu","Rough","Glass Bead","Navillera"],"correct":1,"fun_fact":"Rough closed the group''s school concept trilogy after Glass Bead and Me Gustas Tu, and won 15 music show awards in all.","source":"https://en.wikipedia.org/wiki/GFriend"},{"question":"Which single gave TWICE their first music program award, on M Countdown in May 2016?","options":["Signal","Like Ooh-Ahh","TT","Cheer Up"],"correct":3,"fun_fact":"The win came on May 5, 2016, exactly one year after the first episode of Sixteen, the survival show that formed TWICE.","source":"https://en.wikipedia.org/wiki/Twice"},{"question":"Which song gave MAMAMOO their first music show win, on Inkigayo in March 2016?","options":["Um Oh Ah Yeh","You''re the Best","Décalcomanie","Mr. Ambiguous"],"correct":1,"fun_fact":"It was the title track of their first studio album, Melting, and became their first number-one single. It won eight music shows in total.","source":"https://en.wikipedia.org/wiki/Mamamoo"},{"question":"With Dalla Dalla in February 2019, ITZY won their first music show trophy. On which show?","options":["Show! Music Core","Music Bank","Inkigayo","M Countdown"],"correct":3,"fun_fact":"The win set a record at the time as the fastest music show win by a girl group, and Dalla Dalla went on to collect nine trophies.","source":"https://en.wikipedia.org/wiki/Itzy"},{"question":"ENHYPEN took their first music show win with Drunk-Dazed in May 2021. On which show?","options":["The Show","Music Bank","M Countdown","Show Champion"],"correct":0,"fun_fact":"Drunk-Dazed led their second EP, Border: Carnival, which became the group''s first No. 1 on Japan''s Oricon Albums Chart.","source":"https://en.wikipedia.org/wiki/Enhypen"},{"question":"On which show did TWS take their first music show win, with Plot Twist, 23 days after their 2024 debut?","options":["Show Champion","Music Bank","The Show","Inkigayo"],"correct":0,"fun_fact":"Plot Twist led their debut EP, Sparkling Blue, released on January 22, 2024, the start of what the group labels boyhood pop.","source":"https://en.wikipedia.org/wiki/TWS_(group)"}]'::jsonb, '2026-11-25'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/TVXQ ; https://en.wikipedia.org/wiki/Highlight_(band) ; https://en.wikipedia.org/wiki/Apink ; https://en.wikipedia.org/wiki/Exo ; https://en.wikipedia.org/wiki/GFriend ; https://en.wikipedia.org/wiki/Twice ; https://en.wikipedia.org/wiki/Mamamoo ; https://en.wikipedia.org/wiki/Itzy ; https://en.wikipedia.org/wiki/Enhypen ; https://en.wikipedia.org/wiki/TWS_(group) ; https://en.wikipedia.org/wiki/Hug_(TVXQ_song) ; https://en.wikipedia.org/wiki/Show_the_World ; https://en.wikipedia.org/wiki/Wolf_(Exo_song) ; https://en.wikipedia.org/wiki/Rough_(song) ; https://en.wikipedia.org/wiki/Cheer_Up_(song) ; https://en.wikipedia.org/wiki/Melting_(album) ; https://en.wikipedia.org/wiki/Dalla_Dalla ; https://en.wikipedia.org/wiki/Border:_Carnival ; https://en.wikipedia.org/wiki/Plot_Twist_(TWS_song). Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('NMIXX: From O.O to Blue Valentine', 'Easy questions on NMIXX: Ad Mare, the meaning of their name, the leader, Dice, Party O''Clock, the Fe3O4 series and Blue Valentine.', 18, 'multiple_choice', 'easy', 'group_specific', '[{"question":"What was the title of NMIXX''s debut single album, released on February 22, 2022?","options":["Entwurf","Fe3O4: Break","Expérgo","Ad Mare"],"correct":3,"fun_fact":"Ad Mare is Latin for to the sea. Besides its lead single, it holds the B-side Tank and instrumental versions of both songs.","source":"https://en.wikipedia.org/wiki/Ad_Mare"},{"question":"Which member is the leader of NMIXX?","options":["Lily","Sullyoon","Haewon","Kyujin"],"correct":2,"fun_fact":"In her first solo magazine profile, in the June 2025 issue of Marie Claire Korea, Haewon spoke about her role as the group''s leader.","source":"https://en.wikipedia.org/wiki/Haewon_(singer)"},{"question":"The N in NMIXX stands for now, new, next and which other idea?","options":["The unknown n","Nation","Nature","Night"],"correct":0,"fun_fact":"The word mix stands for combination and diversity, so the full name is meant as the best combination for a new era.","source":"https://en.wikipedia.org/wiki/Nmixx"},{"question":"Which song led NMIXX''s second single album, Entwurf, in September 2022?","options":["Dash","Roller Coaster","Dice","Party O''Clock"],"correct":2,"fun_fact":"Entwurf means draft or design in German. It came out seven months after their debut single album.","source":"https://en.wikipedia.org/wiki/Entwurf"},{"question":"Love Me Like This (2023) was the lead single of NMIXX''s first EP. What is that EP called?","options":["Fe3O4: Forward","Entwurf","Blue Valentine","Expérgo"],"correct":3,"fun_fact":"Expérgo is Latin for to wake up. Released on March 20, 2023, the EP was preceded by the single Young, Dumb, Stupid.","source":"https://en.wikipedia.org/wiki/Expérgo"},{"question":"Which K-pop label founder co-wrote and co-composed Party O''Clock, NMIXX''s July 2023 single?","options":["Bang Si-hyuk","Lee Soo-man","J.Y. Park","Yang Hyun-suk"],"correct":2,"fun_fact":"Party O''Clock led the single album A Midsummer NMIXX''s Dream and was described as a garage-based pop song.","source":"https://en.wikipedia.org/wiki/Party_O''Clock_(Nmixx_song)"},{"question":"Which song led Fe3O4: Break, the EP NMIXX released on January 15, 2024?","options":["Dash","High Horse","See That?","Dice"],"correct":0,"fun_fact":"Dash was described as a cross between old school hip hop and pop punk, and its music video came out the same day as the EP.","source":"https://en.wikipedia.org/wiki/Dash_(Nmixx_song)"},{"question":"Know About Me led which March 2025 EP, the finale of NMIXX''s Fe3O4 series?","options":["Fe3O4: Stick Out","Fe3O4: Forward","Expérgo","Fe3O4: Break"],"correct":1,"fun_fact":"The EP followed Fe3O4: Break and Fe3O4: Stick Out. Its pre-release single, High Horse, came out on March 4, 2025.","source":"https://en.wikipedia.org/wiki/Fe3O4:_Forward"},{"question":"In 2025, Blue Valentine gave NMIXX their first number one on which chart?","options":["Oricon Singles Chart","Circle Digital Chart","Billboard Hot 100","UK Singles Chart"],"correct":1,"fun_fact":"The song led their first studio album of the same name, released in October 2025, and spent four weeks at the top.","source":"https://en.wikipedia.org/wiki/Nmixx"},{"question":"In February 2025, NMIXX made a surprise appearance at the Viña del Mar festival. In which country is it held?","options":["Chile","Argentina","Brazil","Mexico"],"correct":0,"fun_fact":"It made them the first K-pop group ever to perform at the festival, and they were later announced as headliners of the 2026 edition.","source":"https://en.wikipedia.org/wiki/Nmixx"}]'::jsonb, '2026-11-26'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Ad_Mare ; https://en.wikipedia.org/wiki/Haewon_(singer) ; https://en.wikipedia.org/wiki/Nmixx ; https://en.wikipedia.org/wiki/Entwurf ; https://en.wikipedia.org/wiki/Expérgo ; https://en.wikipedia.org/wiki/Party_O''Clock_(Nmixx_song) ; https://en.wikipedia.org/wiki/Dash_(Nmixx_song) ; https://en.wikipedia.org/wiki/Fe3O4:_Forward ; https://nmixx.jype.com/profile ; https://nmixx.jype.com/discography ; https://en.wikipedia.org/wiki/Blue_Valentine_(Nmixx_album). Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop Songs With Numbers', 'From 8282 and 1, 2, 3, 4 to 2 Baddies, 3D and Love 119: ten questions on K-pop songs with a number in the title.', null, 'multiple_choice', 'medium', 'fun', '[{"question":"Which girl group released the tropical house single 4 Walls in October 2015?","options":["Girls'' Generation","f(x)","SISTAR","Apink"],"correct":1,"fun_fact":"4 Walls was the title track of f(x)''s fourth studio album and peaked at No. 2 on the Gaon Digital Chart. LDN Noise co-composed it.","source":"https://en.wikipedia.org/wiki/4_Walls_(song)"},{"question":"SHINee''s 2016 album 1 of 1 had a 1990s theme. On which retro format did it get a limited edition?","options":["8-track cartridge","Vinyl record","MiniDisc","Cassette tape"],"correct":3,"fun_fact":"1 of 1 was SHINee''s fifth Korean studio album. Its November 2016 repackage, 1 and 1, was led by Tell Me What to Do.","source":"https://en.wikipedia.org/wiki/1_of_1_(Shinee_album)"},{"question":"Read aloud, the title of Davichi''s 2009 single 8282 sounds like a Korean word. What does that word mean?","options":["Goodbye","Quickly","Forever","Again"],"correct":1,"fun_fact":"8282 led Davichi in Wonderland, the duo''s first EP, which came out in early 2009.","source":"https://en.wikipedia.org/wiki/Davichi_in_Wonderland"},{"question":"200% was a single from Play, the April 2014 debut album of which K-pop Star 2 winners?","options":["Busker Busker","AKMU","Urban Zakapa","10cm"],"correct":1,"fun_fact":"YG''s Yang Hyun-suk picked 200% as a single while the duo chose Melted. 200% topped the Gaon Digital Chart for two weeks.","source":"https://en.wikipedia.org/wiki/AKMU"},{"question":"Which singer made her debut with the single 1, 2, 3, 4 on October 28, 2012?","options":["Lee Hi","Ailee","Juniel","Hyuna"],"correct":0,"fun_fact":"She had finished second on the first season of K-pop Star before signing with YG Entertainment, and the song was No. 1 on the monthly Gaon Digital Chart for November 2012.","source":"https://en.wikipedia.org/wiki/Lee_Hi"},{"question":"IU''s Twenty-Three was the lead single of which 2015 EP?","options":["Palette","Modern Times","Last Fantasy","Chat-Shire"],"correct":3,"fun_fact":"Released on October 23, 2015, the disco-inspired track topped the Gaon Digital Chart and has sold over 2.5 million downloads in South Korea.","source":"https://en.wikipedia.org/wiki/Twenty-Three_(song)"},{"question":"NCT 127''s 2022 single 2 Baddies has a different Korean title. What does it mean?","options":["Escape","Thunder","Speeding","Gravity"],"correct":2,"fun_fact":"2 Baddies led NCT 127''s fourth studio album, also named 2 Baddies, released by SM Entertainment on September 16, 2022.","source":"https://en.wikipedia.org/wiki/2_Baddies_(song)"},{"question":"Which American rapper is featured on 3D, Jungkook''s single from September 2023?","options":["Latto","Lil Nas X","Jack Harlow","Drake"],"correct":2,"fun_fact":"3D debuted at No. 5 on the Billboard Hot 100, and a November 2023 remix replaced Harlow with Justin Timberlake.","source":"https://en.wikipedia.org/wiki/3D_(song)"},{"question":"Number One Girl, released in November 2024, was a single from which album?","options":["Rosie","Ruby","Born Pink","R"],"correct":0,"fun_fact":"Rosé said the title refers to her fans, whom she calls her number ones. Bruno Mars is among the song''s producers.","source":"https://en.wikipedia.org/wiki/Number_One_Girl"},{"question":"Which boy group released Love 119 in January 2024?","options":["RIIZE","NCT Wish","TWS","The Boyz"],"correct":0,"fun_fact":"Love 119 samples Emergency Room, a 2005 song by the band Izi, and peaked at No. 5 on the Circle Digital Chart.","source":"https://en.wikipedia.org/wiki/Love_119"}]'::jsonb, '2026-11-27'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/4_Walls_(song) ; https://en.wikipedia.org/wiki/1_of_1_(Shinee_album) ; https://en.wikipedia.org/wiki/Davichi_in_Wonderland ; https://en.wikipedia.org/wiki/AKMU ; https://en.wikipedia.org/wiki/Lee_Hi ; https://en.wikipedia.org/wiki/Twenty-Three_(song) ; https://en.wikipedia.org/wiki/2_Baddies_(song) ; https://en.wikipedia.org/wiki/3D_(song) ; https://en.wikipedia.org/wiki/Number_One_Girl ; https://en.wikipedia.org/wiki/Love_119 ; https://en.wikipedia.org/wiki/Play_(AKMU_album) ; https://en.wikipedia.org/wiki/Davichi_discography. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('ATEEZ: The Golden Hour Era', 'Ten questions on the first three parts of ATEEZ''s Golden Hour series (2024 to 2025): Work, Ice on My Teeth, Lemon Drop, charts and festivals.', 14, 'multiple_choice', 'medium', 'era', '[{"question":"Which song led Golden Hour: Part.1, the ATEEZ EP released on May 31, 2024?","options":["Bouncy (K-Hot Chilli Peppers)","Work","Crazy Form","Guerrilla"],"correct":1,"fun_fact":"Part.1 was the group''s tenth EP and opened the Golden Hour series. It debuted at No. 2 on the Billboard 200 and sold over 1.5 million copies in its first week.","source":"https://en.wikipedia.org/wiki/Ateez"},{"question":"In the Work music video, ATEEZ take on odd jobs such as diner shifts and mining for what?","options":["Diamonds","Coal","Gold","Silver"],"correct":2,"fun_fact":"The choreography for Work was co-created by member San, and the song came out the same day as its parent EP.","source":"https://en.wikipedia.org/wiki/Work_(Ateez_song)"},{"question":"Which American rapper joined ATEEZ on Work Pt.4, a remix released in August 2024?","options":["G-Eazy","Pitbull","Flo Rida","Jack Harlow"],"correct":0,"fun_fact":"Work got three official remixes. The first, Work Pt.2, paired the group with Dutch DJ Don Diablo on June 5, 2024.","source":"https://en.wikipedia.org/wiki/Work_(Ateez_song)"},{"question":"Where did Golden Hour: Part.2 debut on the US Billboard 200 in November 2024?","options":["No. 3","No. 1","No. 2","No. 5"],"correct":1,"fun_fact":"The EP earned 184,000 equivalent album units in its first week, giving ATEEZ a second No. 1 after The World EP.Fin: Will in 2023.","source":"https://www.koreatimes.co.kr/www/art/2024/11/398_386975.html"},{"question":"Ice on My Teeth pairs an R&B foundation with which string instrument?","options":["Cello","Harp","Gayageum","Violin"],"correct":3,"fun_fact":"Released on November 15, 2024, the song led the eleventh EP, Golden Hour: Part.2. Yunho described it as a song about knowing your worth.","source":"https://en.wikipedia.org/wiki/Ice_on_My_Teeth"},{"question":"Which ATEEZ single became the group''s first entry on the Billboard Hot 100, in June 2025?","options":["Lemon Drop","Ice on My Teeth","Work","Crazy Form"],"correct":0,"fun_fact":"It entered at No. 69, making ATEEZ the third Korean boy band to reach the Hot 100. It led Golden Hour: Part.3, released June 13, 2025.","source":"https://en.wikipedia.org/wiki/Golden_Hour:_Part.3"},{"question":"Which title song led the In Your Fantasy Edition of Golden Hour: Part.3 in July 2025?","options":["Wave","Adrenaline","In Your Fantasy","Answer"],"correct":2,"fun_fact":"The deluxe edition came out on July 11, 2025, and its title song entered the Billboard Hot 100 at No. 68, weeks after Lemon Drop.","source":"https://en.wikipedia.org/wiki/Ateez"},{"question":"ATEEZ played which US festival in April 2024, a first for any K-pop boy group?","options":["Lollapalooza","Austin City Limits","Governors Ball","Coachella"],"correct":3,"fun_fact":"They played the festival on April 12 and 19, 2024, and on April 20 they threw the first pitch at a Los Angeles Dodgers game.","source":"https://en.wikipedia.org/wiki/Ateez"},{"question":"ATEEZ headlined the Mawazine festival on June 23, 2024. In which country is the festival held?","options":["Egypt","Morocco","Saudi Arabia","Tunisia"],"correct":1,"fun_fact":"Mawazine takes place in Rabat. ATEEZ were the first K-pop act to headline it, years after filming their debut video in the Moroccan Sahara.","source":"https://en.wikipedia.org/wiki/Mawazine"},{"question":"On the 2025 European leg of the Towards the Light: Will to Power tour, ATEEZ sold out which Paris venue?","options":["Accor Arena","Stade de France","Paris La Défense Arena","Zénith Paris"],"correct":2,"fun_fact":"ATEEZ became the first K-pop group to headline a sold-out show at this arena, which is billed as the largest indoor venue in Europe.","source":"https://en.wikipedia.org/wiki/Ateez"}]'::jsonb, '2026-11-28'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Ateez ; https://en.wikipedia.org/wiki/Golden_Hour:_Part.1 ; https://en.wikipedia.org/wiki/Work_(Ateez_song) ; https://en.wikipedia.org/wiki/Golden_Hour:_Part.2 ; https://www.koreatimes.co.kr/www/art/2024/11/398_386975.html ; https://en.wikipedia.org/wiki/Ice_on_My_Teeth ; https://en.wikipedia.org/wiki/Golden_Hour:_Part.3 ; https://en.wikipedia.org/wiki/Lemon_Drop_(song) ; https://en.wikipedia.org/wiki/Mawazine. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('Wonder Girls True or False', 'Ten true or false statements on Wonder Girls, from the 2007 JYP debut and Tell Me to the US tour, the Reboot band era and the 2017 farewell.', 45, 'true_false', 'hard', 'true_false', '[{"question":"Wonder Girls made their February 2007 debut with the single Tell Me.","correct":false,"fun_fact":"Their debut single was Irony, from the EP The Wonder Begins. Tell Me arrived later in 2007 as the lead single of The Wonder Years.","source":"https://en.wikipedia.org/wiki/Wonder_Girls"},{"question":"Before their debut, the members were introduced to viewers in a TV show called MTV Wonder Girls.","correct":true,"fun_fact":"At their first showcase in the MTV studio, the group covered Don''t Cha by the Pussycat Dolls alongside original songs such as Irony.","source":"https://en.wikipedia.org/wiki/Wonder_Girls"},{"question":"Tell Me, the group''s 2007 hit, samples the 1986 song Two of Hearts by Stacey Q.","correct":true,"fun_fact":"Written and produced by Park Jin-young, Tell Me spent six non-consecutive weeks at No. 1 on KBS''s Music Bank.","source":"https://en.wikipedia.org/wiki/Tell_Me_(Wonder_Girls_song)"},{"question":"So Hot was first released in 2009, after the group had begun its US activities.","correct":false,"fun_fact":"So Hot came out on May 22, 2008, four months before Nobody, and it topped online charts soon after its release.","source":"https://en.wikipedia.org/wiki/Wonder_Girls"},{"question":"On the 2009 Jonas Brothers World Tour, Wonder Girls opened only 13 of the North American shows.","correct":false,"fun_fact":"The group was first booked for 13 dates but ended up joining the Jonas Brothers for a total of 45 concerts.","source":"https://en.wikipedia.org/wiki/Wonder_Girls"},{"question":"The 2010 single 2 Different Tears was recorded in Korean, English and Japanese.","correct":false,"fun_fact":"It was recorded in Korean, English and Chinese, and its video features cameos by Park Jin-young and comedian Bobby Lee.","source":"https://en.wikipedia.org/wiki/Wonder_Girls"},{"question":"In 2012, the group starred in a TV movie, The Wonder Girls, broadcast on the US channel TeenNick.","correct":true,"fun_fact":"The film premiered on February 2, 2012 and featured Like Money, an English-language song that had not been released yet.","source":"https://en.wikipedia.org/wiki/Wonder_Girls"},{"question":"In the band lineup of the 2015 album Reboot, Sunmi was the group''s drummer.","correct":false,"fun_fact":"Sunmi played bass, Yubin drums, Hyerim guitar and Yeeun piano. I Feel You served as the album''s lead single.","source":"https://en.wikipedia.org/wiki/Reboot_(Wonder_Girls_album)"},{"question":"Why So Lonely, released in July 2016, was the first Wonder Girls single not written by J.Y. Park.","correct":true,"fun_fact":"Hyerim, Sunmi and Yubin wrote it with Hong Ji-sang, and the reggae-pop track went to No. 1 on the Gaon Digital Chart.","source":"https://en.wikipedia.org/wiki/Why_So_Lonely"},{"question":"The group''s final single, Draw Me, came out in February 2017 to celebrate ten years since their debut.","correct":true,"fun_fact":"Draw Me was released on February 10, 2017, about two weeks after JYP Entertainment announced the end of the group.","source":"https://en.wikipedia.org/wiki/Wonder_Girls"}]'::jsonb, '2026-11-29'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Wonder_Girls ; https://www.wikidata.org/wiki/Q476119 ; https://en.wikipedia.org/wiki/Tell_Me_(Wonder_Girls_song) ; https://en.wikipedia.org/wiki/Reboot_(Wonder_Girls_album) ; https://en.wikipedia.org/wiki/Why_So_Lonely. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('Red Velvet: From Happiness to Cosmic', 'Ten easy questions on Red Velvet''s first ten years with SM, from the 2014 debut Happiness to Feel My Rhythm, Chill Kill and Cosmic.', 13, 'multiple_choice', 'easy', 'group_specific', '[{"question":"Which single did Red Velvet debut with in August 2014?","options":["Be Natural","Dumb Dumb","Automatic","Happiness"],"correct":3,"fun_fact":"Chad Hugo of The Neptunes co-produced the song, and the four-member group gave its debut stage on KBS''s Music Bank.","source":"https://en.wikipedia.org/wiki/Happiness_(Red_Velvet_song)"},{"question":"Which member joined Red Velvet in March 2015, turning the quartet into a five-piece?","options":["Yeri","Wendy","Seulgi","Joy"],"correct":0,"fun_fact":"She was introduced just before the first EP, Ice Cream Cake, whose title track video was filmed in a desert near Palmdale, California.","source":"https://en.wikipedia.org/wiki/Ice_Cream_Cake_(song)"},{"question":"Which 2016 EP put the spotlight on Red Velvet''s softer, R&B-leaning velvet concept, after the album The Red?","options":["Rookie","The Velvet","Russian Roulette","Queendom"],"correct":1,"fun_fact":"Released on March 17, 2016 and led by One of These Nights, it answered The Red, which had shown the group''s brighter red concept.","source":"https://en.wikipedia.org/wiki/Red_Velvet_(group)"},{"question":"Which Red Velvet song, first released in 2016, was later heard in the animated film Trolls World Tour?","options":["Bad Boy","Peek-a-Boo","Russian Roulette","Feel My Rhythm"],"correct":2,"fun_fact":"It led the group''s third EP in September 2016, and its cartoon-style video shows the members playing tricks on each other.","source":"https://en.wikipedia.org/wiki/Russian_Roulette_(Red_Velvet_song)"},{"question":"In April 2018, Red Velvet sang Bad Boy at the concert Spring Is Coming. In which city was it held?","options":["Seoul","Incheon","Busan","Pyongyang"],"correct":3,"fun_fact":"The show made Red Velvet the first SM Entertainment act in fifteen years, since Shinhwa, to perform in North Korea.","source":"https://en.wikipedia.org/wiki/Bad_Boy_(Red_Velvet_song)"},{"question":"Feel My Rhythm (2022) samples Air on the G String by which composer?","options":["Mozart","Beethoven","Vivaldi","Bach"],"correct":3,"fun_fact":"The music video is staged like an opera and pays homage to famous artworks such as The Swing and Ophelia.","source":"https://en.wikipedia.org/wiki/Feel_My_Rhythm"},{"question":"Chill Kill, released in November 2023, was Red Velvet''s first Korean studio album since which year?","options":["2015","2017","2019","2021"],"correct":1,"fun_fact":"The previous one was Perfect Velvet in 2017. Chill Kill holds ten tracks, led by the title song of the same name.","source":"https://en.wikipedia.org/wiki/Red_Velvet_(group)"},{"question":"Which EP did Red Velvet release in June 2024, shortly before the group''s 10th anniversary?","options":["Queendom","Cosmic","Summer Magic","Velvet Summer"],"correct":1,"fun_fact":"A new version with the extra song Sweet Dreams came out on August 1, 2024, to mark the 10th anniversary.","source":"https://en.wikipedia.org/wiki/Cosmic_(EP)"},{"question":"With which EP did the sub-unit Irene & Seulgi debut in July 2020?","options":["Queendom","Tilt","Monster","Rookie"],"correct":2,"fun_fact":"Their cover of S.E.S.''s Be Natural as SM Rookies helped inspire the unit, which returned with the EP Tilt in May 2025.","source":"https://en.wikipedia.org/wiki/Red_Velvet_%E2%80%93_Irene_%26_Seulgi"},{"question":"What was the name of Red Velvet''s first solo concert, held in August 2017?","options":["Red Room","La Rouge","Redmare","R to V"],"correct":0,"fun_fact":"A third show was added because of demand, and the Red Room concerts were later taken to Japan in 2018.","source":"https://en.wikipedia.org/wiki/Red_Velvet_(group)"}]'::jsonb, '2026-11-30'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Red_Velvet_(group) ; https://www.wikidata.org/wiki/Q17466114 ; https://en.wikipedia.org/wiki/Happiness_(Red_Velvet_song) ; https://en.wikipedia.org/wiki/Ice_Cream_Cake_(song) ; https://en.wikipedia.org/wiki/Russian_Roulette_(Red_Velvet_song) ; https://en.wikipedia.org/wiki/Bad_Boy_(Red_Velvet_song) ; https://en.wikipedia.org/wiki/Feel_My_Rhythm ; https://en.wikipedia.org/wiki/Chill_Kill ; https://en.wikipedia.org/wiki/Cosmic_(EP) ; https://en.wikipedia.org/wiki/Red_Velvet_%E2%80%93_Irene_%26_Seulgi. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop Groups That Debuted in 2025', 'Hard questions on K-pop groups that debuted in 2025: the labels behind them, the shows that formed them and the releases they debuted with.', null, 'multiple_choice', 'hard', 'knowledge', '[{"question":"Which agency launched Hearts2Hearts, who debuted on February 24, 2025 with The Chase?","options":["JYP Entertainment","SM Entertainment","Starship Entertainment","Cube Entertainment"],"correct":1,"fun_fact":"The group name contains S2, a nod to a heart emoticon, and the group was first revealed by a surprise trailer at an SM Town concert in January 2025.","source":"https://en.wikipedia.org/wiki/Hearts2Hearts"},{"question":"KiiiKiii debuted in March 2025 with the EP Uncut Gem. Which label formed the group?","options":["Starship Entertainment","Woollim Entertainment","Pledis Entertainment","FNC Entertainment"],"correct":0,"fun_fact":"The name plays on kiki, a Korean sound for giggling, and on the English word key.","source":"https://en.wikipedia.org/wiki/KiiiKiii"},{"question":"Which song led KickFlip''s debut EP, Flip It, Kick It!, released in January 2025?","options":["Eye-Poppin''","Mama Said","Rendezvous","Chan-Ran"],"correct":1,"fun_fact":"J.Y. Park first teased the group at the 2024 MAMA Awards in Los Angeles, and its name comes from a skateboarding trick.","source":"https://en.wikipedia.org/wiki/KickFlip"},{"question":"With which single did BigHit Music''s CORTIS officially debut on August 18, 2025?","options":["Fashion","RedRed","Pretty Please","What You Want"],"correct":3,"fun_fact":"The choreography for the debut single is danced on treadmills. CORTIS is BigHit Music''s third group after BTS and Tomorrow X Together.","source":"https://en.wikipedia.org/wiki/Cortis"},{"question":"Which label formed ALLDAY PROJECT, a co-ed group that debuted in June 2025 with the single album Famous?","options":["P Nation","KQ Entertainment","The Black Label","Antenna"],"correct":2,"fun_fact":"The name AllDay was reportedly coined by will.i.am of Black Eyed Peas when he first saw the five members together.","source":"https://en.wikipedia.org/wiki/AllDay_Project"},{"question":"Through which SBS survival show was AHOF formed before its July 2025 debut?","options":["Project 7","Universe League","Debut''s Plan","Boys Planet"],"correct":1,"fun_fact":"AHOF stands for All-time Hall Of Famer, and it sounds like the Korean word for nine, a nod to the group''s nine members.","source":"https://en.wikipedia.org/wiki/AHOF"},{"question":"Which boy group came out of JTBC''s Project 7 and debuted in April 2025 with the EP Eternalt?","options":["Close Your Eyes","IDID","NouerA","AxMxP"],"correct":0,"fun_fact":"The group is managed by Uncore, a label set up by SLL and YG Plus, and won its first music show trophy six days after debut.","source":"https://en.wikipedia.org/wiki/Close_Your_Eyes_(group)"},{"question":"IDID, formed through Starship''s show Debut''s Plan, debuted in September 2025 with which EP?","options":["I Did It.","Uncut Gem","Push Back","Who We Are"],"correct":0,"fun_fact":"IDID was Starship''s first new boy group in five years, since Cravity, and the debut EP was led by the single Chan-Ran.","source":"https://en.wikipedia.org/wiki/Idid_(group)"},{"question":"Baby DONT Cry, a P Nation girl group, debuted on June 23, 2025 with which single album?","options":["Girls Never Die","Supernatural","Lucky Girl Syndrome","F Girl"],"correct":3,"fun_fact":"Its title song of the same name pushes back against judging people only by their achievements and numbers.","source":"https://en.wikipedia.org/wiki/Baby_Dont_Cry"},{"question":"AtHeart, who debuted in August 2025 with the EP Plot Twist, were formed by which American agency?","options":["Hi-Hat Entertainment","Modhaus","Titan Content","Beat Interactive"],"correct":2,"fun_fact":"Titan Content was co-founded in November 2023 by Nikki Semin-Han, a former chief executive of SM Entertainment.","source":"https://en.wikipedia.org/wiki/AtHeart"}]'::jsonb, '2026-12-01'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Hearts2Hearts ; https://www.wikidata.org/wiki/Q131746784 ; https://en.wikipedia.org/wiki/KiiiKiii ; https://www.wikidata.org/wiki/Q132526762 ; https://en.wikipedia.org/wiki/KickFlip ; https://www.wikidata.org/wiki/Q131722593 ; https://en.wikipedia.org/wiki/Cortis ; https://www.wikidata.org/wiki/Q135668928 ; https://en.wikipedia.org/wiki/AllDay_Project ; https://www.wikidata.org/wiki/Q134986635 ; https://en.wikipedia.org/wiki/AHOF ; https://en.wikipedia.org/wiki/Close_Your_Eyes_(group) ; https://www.wikidata.org/wiki/Q131689681 ; https://en.wikipedia.org/wiki/Idid_(group) ; https://www.wikidata.org/wiki/Q135466598 ; https://en.wikipedia.org/wiki/P_Nation ; https://en.wikipedia.org/wiki/Baby_Dont_Cry ; https://en.wikipedia.org/wiki/AtHeart ; https://www.wikidata.org/wiki/Q28700294 ; https://en.wikipedia.org/wiki/2025_in_South_Korean_music. Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.'),
  ('K-pop Winter and Christmas Songs', 'A festive, easy quiz: match ten K-pop winter and Christmas releases, from BoA''s Merry-Chri to GOT7''s Winter Heptagon, with the acts behind them.', null, 'multiple_choice', 'easy', 'fun', '[{"question":"Which girl group released Merry & Happy, a Christmas reissue of its first studio album, in December 2017?","options":["Red Velvet","Apink","GFriend","TWICE"],"correct":3,"fun_fact":"The reissue of Twicetagram added two new songs: Heart Shaker and the title song Merry & Happy, written by J.Y. Park.","source":"https://en.wikipedia.org/wiki/Merry_%26_Happy"},{"question":"Christmas EveL, a holiday single album from November 2021, comes from which boy band?","options":["ATEEZ","The Boyz","TXT","Stray Kids"],"correct":3,"fun_fact":"The title is read as Christmas Evil, and Winter Falls served as its second lead single.","source":"https://en.wikipedia.org/wiki/Christmas_EveL"},{"question":"Which NCT unit released the special winter EP Candy in December 2022?","options":["NCT Dream","NCT 127","WayV","NCT Wish"],"correct":0,"fun_fact":"The title song remakes Candy, a 1996 hit by H.O.T., and all six tracks on the EP have a Christmas theme.","source":"https://en.wikipedia.org/wiki/Candy_(EP)"},{"question":"Which SM singer released the Christmas EP This Christmas: Winter Is Coming in 2017?","options":["Taeyeon","Kyuhyun","Wendy","Hyoyeon"],"correct":0,"fun_fact":"To promote it, she held three Christmas concerts called The Magic of Christmas Time from December 22 to 24, 2017.","source":"https://en.wikipedia.org/wiki/This_Christmas:_Winter_Is_Coming"},{"question":"Which singer-songwriter released Winter Flower, featuring RM of BTS, in January 2020?","options":["Heize","Younha","Lee Hi","Baek Ye-rin"],"correct":1,"fun_fact":"RM helped write the lyrics, and because of their schedules the two made the song remotely, by phone and email.","source":"https://en.wikipedia.org/wiki/Winter_Flower"},{"question":"Who sang Merry Christmas Ahead, the 2010 holiday song featuring Thunder of MBLAQ?","options":["Ailee","Hyuna","IU","Gummy"],"correct":2,"fun_fact":"It first appeared as a B-side on her EP Real, and it has re-entered Korean charts in December year after year.","source":"https://en.wikipedia.org/wiki/Merry_Christmas_Ahead"},{"question":"Which group reunited in January 2025 with Winter Heptagon, an EP led by Python?","options":["BTOB","2PM","GOT7","Highlight"],"correct":2,"fun_fact":"The members wrote and composed every song, and the release, the first in three years, coincided with the group''s 11th anniversary.","source":"https://en.wikipedia.org/wiki/Winter_Heptagon"},{"question":"Merry-Chri, a 2004 single that became a Christmas favorite in Japan, was released by which singer?","options":["Lee Hyori","BoA","Sunmi","Ailee"],"correct":1,"fun_fact":"She wrote the Korean lyrics herself, and the American rock band Weezer later recorded a cover of the song.","source":"https://en.wikipedia.org/wiki/Meri_Kuri"},{"question":"Red Velvet teamed up with which girl group on Beautiful Christmas, lead single of 2022 Winter SM Town: SMCU Palace?","options":["f(x)","S.E.S.","aespa","Hearts2Hearts"],"correct":2,"fun_fact":"The album was SM Town''s tenth winter album, released on December 26, 2022, and 58 of the label''s artists took part in it.","source":"https://en.wikipedia.org/wiki/2022_Winter_SM_Town:_SMCU_Palace"},{"question":"Which BTS member sang Christmas Tree for the soundtrack of the 2021 drama Our Beloved Summer?","options":["Jin","V","Jimin","Jungkook"],"correct":1,"fun_fact":"The song was released on December 24, 2021, Christmas Eve, by Most Contents.","source":"https://en.wikipedia.org/wiki/Christmas_Tree_(V_song)"}]'::jsonb, '2026-12-02'::date, 'verified', now(), 'Sources: https://en.wikipedia.org/wiki/Merry_%26_Happy ; https://en.wikipedia.org/wiki/Christmas_EveL ; https://en.wikipedia.org/wiki/Candy_(EP) ; https://en.wikipedia.org/wiki/This_Christmas:_Winter_Is_Coming ; https://en.wikipedia.org/wiki/Winter_Flower ; https://en.wikipedia.org/wiki/Merry_Christmas_Ahead ; https://en.wikipedia.org/wiki/Winter_Heptagon ; https://en.wikipedia.org/wiki/Meri_Kuri ; https://en.wikipedia.org/wiki/2022_Winter_SM_Town:_SMCU_Palace ; https://en.wikipedia.org/wiki/Christmas_Tree_(V_song). Drafted with AI assistance, checked by {REVIEWER} on {REVIEW_DATE}.');

-- Check: every row this file just inserted (verified_at = now(), the start of this transaction) is a
-- kpop row (no site_id column yet, or site_id 'kpop'). If not, nothing is applied.
do $$
begin
  if exists (
    select 1 from public.quiz_bank qb
    where qb.verified_at = now() and qb.title in ('ZEROBASEONE: From Boys Planet to In Bloom', 'K-pop Agency Founders', 'LE SSERAFIM: The EASY to HOT Era', 'K-pop Songs About Magic', 'TREASURE True or False', 'DAY6: From Congratulations to Fourever', 'TXT: From Sugar Rush Ride to Deja Vu', 'K-pop Songs of 2025', 'KPop Demon Hunters Quiz', 'BOYNEXTDOOR: From WHO! to No Genre', 'K-pop Award Shows True or False', 'IVE: The SWITCH to EMPATHY Era', 'K-pop Groups and Their First Wins', 'NMIXX: From O.O to Blue Valentine', 'K-pop Songs With Numbers', 'ATEEZ: The Golden Hour Era', 'Wonder Girls True or False', 'Red Velvet: From Happiness to Cosmic', 'K-pop Groups That Debuted in 2025', 'K-pop Winter and Christmas Songs') and not (coalesce(to_jsonb(qb) ->> 'site_id', 'kpop') = 'kpop')
  ) then
    raise exception 'daily bank lot 2: a row of this lot is not a kpop row, nothing applied';
  end if;
end $$;

-- Check: the review is recorded. While {REVIEWER} or {REVIEW_DATE} is still in the notes, nothing is applied.
do $$
begin
  if exists (select 1 from public.quiz_bank qb where qb.verified_at = now() and qb.verification_notes ~ '[{](REVIEWER|REVIEW_DATE)[}]') then
    raise exception 'daily bank lot 2: review not recorded (replace {REVIEWER} and {REVIEW_DATE}), nothing applied';
  end if;
end $$;

-- Check: one kpop row per date, no clash with a row already scheduled on these dates.
select scheduled_date, count(*) from public.quiz_bank qb
where scheduled_date between '2026-11-13' and '2026-12-02' and status in ('verified', 'scheduled') and coalesce(to_jsonb(qb) ->> 'site_id', 'kpop') = 'kpop'
group by scheduled_date having count(*) > 1;

commit;
